def initialize_catalog(apps, schema_editor):
    from django.utils import timezone
    alias = schema_editor.connection.alias
    Catalog = apps.get_model("commercial", "CatalogRevision")
    Approval = apps.get_model("commercial", "OperationalApproval")
    catalogs = Catalog.objects.using(alias)
    if not catalogs.filter(is_active=True).exists():
        row = catalogs.filter(revision=LAUNCH_CATALOG["revision"]).first()
        if row is None:
            row = catalogs.create(revision=LAUNCH_CATALOG["revision"], specification=LAUNCH_CATALOG, published_at=timezone.now())
        catalogs.filter(pk=row.pk).update(is_active=True)
    for purpose in APPROVAL_PURPOSES:
        Approval.objects.using(alias).get_or_create(purpose=purpose, defaults={"state": "pending"})
    Approval.objects.using(alias).get_or_create(purpose="maintenance", defaults={"state": "inactive"})


